OVERRIDE='\n# ---------------------------------------------------------------------------\n# V4.2.3 stability overrides — intentionally appended instead of source surgery\n# ---------------------------------------------------------------------------\ndef _v423_is_facebook_url(url):\n    try:\n        host=(urlparse(url or "").netloc or "").lower()\n        return host=="facebook.com" or host.endswith(".facebook.com") or host=="fb.com" or host.endswith(".fb.com")\n    except Exception:\n        return False\n\n\ndef _v423_facebook_candidate(href):\n    href=unescape((href or "").strip())\n    if not href:return ""\n    if href.startswith("//"):href="https:"+href\n    try:\n        p=urlparse(href)\n        if "duckduckgo.com" in (p.netloc or "").lower():\n            qs=parse.parse_qs(p.query)\n            href=parse.unquote((qs.get("uddg") or [""])[0])\n            p=urlparse(href)\n        host=(p.netloc or "").lower()\n        if not (host=="facebook.com" or host.endswith(".facebook.com") or host=="fb.com" or host.endswith(".fb.com")):return ""\n        low=(p.path or "").lower()\n        if any(x in low for x in ("/login","/help","/marketplace","/watch","/reel","/share","/groups/","/events/","/photo")):return ""\n        return ("https://"+(p.netloc or "www.facebook.com")+(p.path or "/")).rstrip("/")\n    except Exception:\n        return ""\n\n\ndef _v423_transient_kind(ex):\n    msg=str(ex or "").lower()\n    try:kind=_service_failure_kind("pipeline",ex)\n    except Exception:kind="error"\n    if any(x in msg for x in ("http 408","http 429","http 500","http 502","http 503","http 504","http 520","http 521","http 522","http 523","http 524","service unavailable","bad gateway","gateway timeout","timed out","timeout","connection reset","remote end closed","urlopen error")):\n        return "temporary" if kind not in ("quota","auth") else kind\n    return kind\n\n\ndef _v423_transient_call(label, fn, job_id="", company="", attempts=4):\n    waits=(2,5,10,20,40)\n    last=None\n    for attempt in range(1,max(2,int(attempts))+1):\n        try:return fn()\n        except Exception as ex:\n            last=ex;kind=_v423_transient_kind(ex)\n            if kind not in ("temporary","rate_limit") or attempt>=attempts:raise\n            delay=waits[min(attempt-1,len(waits)-1)]\n            if job_id:\n                _job_set(job_id,detail=f"Temporary {label} problem — retrying in {delay}s • {company}",failure_kind=kind,company=company)\n            time.sleep(delay)\n    raise last\n\n\ndef _v423_find_facebook(l, job_id="", company=""):\n    if not isinstance(l,dict):return {"found":False,"reason":"Invalid prospect"}\n    if l.get("facebook_url"):return {"found":True,"url":l.get("facebook_url"),"title":l.get("facebook_title") or l.get("company") or ""}\n    if _v423_is_facebook_url(l.get("website")):return {"found":True,"url":l.get("website"),"title":l.get("company") or ""}\n    name=(l.get("company") or "").strip()\n    if not name:return {"found":False,"reason":"No company name"}\n    loc=(l.get("postcode") or l.get("address") or "United Kingdom")\n    q=f\'"{name}" {loc} site:facebook.com\'\n    search_url="https://html.duckduckgo.com/html/?q="+parse.quote(q)\n    if job_id:_job_set(job_id,detail=f"No website found — checking Facebook • {company or name}",company=company or name,current_url="")\n    try:\n        def go():\n            req=request.Request(search_url,headers={"User-Agent":"Mozilla/5.0 (compatible; YMSProspectFinder/4.2.3; business research)","Accept":"text/html"})\n            with request.urlopen(req,timeout=12) as r:return r.read(350000).decode("utf-8","ignore")\n        raw=_v423_transient_call("Facebook lookup",go,job_id,company or name,3)\n    except Exception as ex:\n        return {"found":False,"reason":"Facebook lookup unavailable: "+str(ex)[:140]}\n    rows=[]\n    for href,title_html in re.findall(r\'(?is)<a[^>]+class=["\\\'][^"\\\']*result__a[^"\\\']*["\\\'][^>]+href=["\\\']([^"\\\']+)["\\\'][^>]*>(.*?)</a>\',raw):\n        fb=_v423_facebook_candidate(href)\n        if not fb:continue\n        title=html_text(title_html)\n        score=SequenceMatcher(None,norm_name(name),norm_name(title)).ratio()\n        name_words=set(re.findall(r"[a-z0-9]+",norm_name(name)))\n        path_words=set(re.findall(r"[a-z0-9]+",urlparse(fb).path.lower()))\n        if name_words and path_words:score+=min(.22,.055*len(name_words & path_words))\n        rows.append((score,fb,title))\n    if not rows:return {"found":False,"reason":"No likely Facebook business page found"}\n    rows.sort(reverse=True,key=lambda x:x[0]);score,fb,title=rows[0]\n    if score<.50:return {"found":False,"reason":"Facebook results were too ambiguous"}\n    return {"found":True,"url":fb,"title":title,"match_score":round(min(score,1)*100)}\n\n\ndef _v423_facebook_evidence(l, progress=None):\n    fb=l.get("facebook_url") or ""\n    if not fb:return {"text":"","pages":[],"attempted_pages":[],"evidence_pages":[],"fetched_at":nowiso(),"source":"none"}\n    if progress:progress(0,1,"Checking public Facebook page",fb,0)\n    snippets=[]\n    try:\n        raw,final=fetch_html(fb,timeout=12,max_bytes=300000);fb=final or fb\n        for pat in (\n            r\'(?is)<meta[^>]+property=["\\\']og:description["\\\'][^>]+content=["\\\']([^"\\\']+)\',\n            r\'(?is)<meta[^>]+name=["\\\']description["\\\'][^>]+content=["\\\']([^"\\\']+)\',\n            r\'(?is)<meta[^>]+property=["\\\']og:title["\\\'][^>]+content=["\\\']([^"\\\']+)\'):\n            m=re.search(pat,raw)\n            if m:snippets.append(unescape(m.group(1)))\n    except Exception:\n        pass\n    text=re.sub(r"\\s+"," "," ".join([l.get("company") or "",l.get("address") or "",l.get("sector") or ""]+snippets)).strip()\n    if progress:progress(1,1,"Facebook checked",fb,1 if len(text)>=120 else 0)\n    return {"text":text[:12000],"pages":[fb] if text else [],"attempted_pages":[fb],"evidence_pages":[fb] if text else [],"fetched_at":nowiso(),"source":"Facebook public page","facebook_url":fb}\n\n\ndef _v423_resolve_presence(id_, l, job_id="", company=""):\n    if not l:return l\n    company=company or l.get("company") or "Prospect"\n    if _v423_is_facebook_url(l.get("website")):\n        fb=l.get("website")\n        def move(x):x["facebook_url"]=fb;x["facebook_checked_at"]=nowiso();x["website"]="";return dict(x)\n        l=update_lead(id_,move) or get_lead(id_) or l\n    if not l.get("website") and not l.get("place_id"):\n        try:\n            if job_id:_job_set(job_id,detail=f"Finding company on Google • {company}",company=company,current_url="")\n            r=_v423_transient_call("Google lookup",lambda:resolve_google_for_ch(l),job_id,company,3)\n            if r.get("matched"):\n                def apply_resolve(x):merge_into(x,r["lead"]);return dict(x)\n                l=update_lead(id_,apply_resolve) or get_lead(id_) or l\n        except Exception:pass\n    if not l.get("website") and l.get("place_id"):\n        key=cfg().get("google_places_key")\n        if key:\n            try:\n                if job_id:_job_set(job_id,detail=f"Finding company website • {company}",company=company,current_url="")\n                p2=_v423_transient_call("Google Places",lambda:google_details(l["place_id"],key,"enterprise"),job_id,company,3)\n                def apply_place(x):merge_into(x,gp_to_lead(p2,x.get("sector",""),"Google enterprise enrichment"));return dict(x)\n                l=update_lead(id_,apply_place) or get_lead(id_) or l\n            except Exception:pass\n    if _v423_is_facebook_url(l.get("website")):\n        fb=l.get("website")\n        def move2(x):x["facebook_url"]=fb;x["facebook_checked_at"]=nowiso();x["website"]="";return dict(x)\n        l=update_lead(id_,move2) or get_lead(id_) or l\n    if not l.get("website") and not l.get("facebook_url"):\n        fb=_v423_find_facebook(l,job_id,company)\n        def save_fb(x):\n            x["facebook_checked_at"]=nowiso()\n            if fb.get("found"):\n                x["facebook_url"]=fb.get("url","");x["facebook_title"]=fb.get("title","");x["facebook_match_score"]=fb.get("match_score",0);x.pop("web_skip_reason",None)\n            else:x["facebook_lookup_reason"]=fb.get("reason","")\n            return dict(x)\n        l=update_lead(id_,save_fb) or get_lead(id_) or l\n    return l\n\n\ndef _v423_collect_evidence(id_,l,progress=None,job_id="",company=""):\n    if l.get("website"):\n        return _v423_transient_call("website",lambda:web_enrich(l,progress),job_id,company or l.get("company") or "",3)\n    if l.get("facebook_url"):\n        return _v423_facebook_evidence(l,progress)\n    return {"text":"","pages":[],"attempted_pages":[],"evidence_pages":[],"fetched_at":nowiso(),"source":"none"}\n\n\n# Override the old short retry window. 503/429/5xx now wait and retry automatically.\ndef _ai_with_retry(job_id, lead, base_pct, span, company):\n    waits=(2,5,10,20,40)\n    for attempt in range(1,7):\n        try:return ai_analyse(lead)\n        except Exception as ex:\n            kind=_v423_transient_kind(ex)\n            if kind in ("quota","auth","error") or attempt>=6:raise\n            delay=waits[min(attempt-1,len(waits)-1)]\n            _job_set(job_id,detail=f"Temporary OpenAI issue — retry {attempt}/5 in {delay}s • {company}",failure_kind=kind,company=company,percent=round(base_pct+span*.34,1))\n            time.sleep(delay)\n\n\n# Smart Finder and one-click pipeline both use the same web-presence fallback.\ndef _process_pipeline_lead(id_, job_id="", company_index=0, total=0):\n    l=get_lead(id_);company=(l or {}).get("company") or "Prospect"\n    if not l:raise SkipProspect("Prospect record was not found")\n    done,why=_action_complete(l,"pipeline")\n    if done:return {"status":"already","reason":why,"company":company}\n    if hard_noise_reason(l) or l.get("discovery_excluded"):\n        raise SkipProspect(l.get("discovery_exclusion_reason") or "Obvious non-industrial / irrelevant result")\n    if not l.get("ai"):\n        l=_v423_resolve_presence(id_,l,job_id,company) or get_lead(id_) or l\n        if not l.get("website") and not l.get("facebook_url"):\n            reason="No company website or Facebook business page found"\n            update_lead(id_,lambda x:(x.update({"web_skip_reason":reason,"ai_skip_reason":reason}) or True))\n            raise SkipProspect(reason)\n        ev=l.get("web_evidence") or {}\n        if not ev.get("text"):\n            def progress(i,n,msg,url,pages):\n                if job_id:_job_set(job_id,detail=f"{msg} • {company}",current_url=url,page_index=i,page_total=n,pages_found=pages,company=company)\n            current=l.get("website") or l.get("facebook_url") or ""\n            if job_id:_job_set(job_id,detail=f"Reading public business evidence • {company}",company=company,current_url=current)\n            def enrich(x):\n                ev2=_v423_collect_evidence(id_,x,progress,job_id,company);x["web_evidence"]=ev2;x["emails"]=merge_lists(x.get("emails",[]),ev2.get("emails",[]))\n                if ev2.get("contact_page"):x["contact_page"]=ev2["contact_page"]\n                if ev2.get("linkedin_url"):x["linkedin_url"]=ev2["linkedin_url"]\n                x.pop("web_skip_reason",None);return ev2\n            ev=update_lead(id_,enrich) or {}\n            if len((ev.get("text") or "").strip())<120:\n                reason="Facebook page found, but not enough public evidence could be read" if l.get("facebook_url") and not l.get("website") else "No usable website evidence"\n                update_lead(id_,lambda x:(x.update({"web_skip_reason":reason,"ai_skip_reason":reason}) or True))\n                raise SkipProspect(reason)\n        gate_fn=globals().get("apply_website_relevance_gate")\n        if callable(gate_fn):\n            gate=gate_fn(id_)\n            if not gate.get("pass"):\n                reason="Filtered before AI — "+str(gate.get("reason") or "not relevant")\n                update_lead(id_,lambda x:(x.update({"ai_skip_reason":reason}) or True));raise SkipProspect(reason)\n        l=get_lead(id_) or l\n        if job_id:_job_set(job_id,detail=f"AI qualifying • {company}",company=company,current_url=(l.get("website") or l.get("facebook_url") or ""))\n        result=_ai_with_retry(job_id,l,0,0,company)\n        if job_id:_job_set(job_id,detail=f"Saving priority + email draft • {company}",company=company,current_url="")\n        def save_ai(x):x["ai"]=result;x.pop("ai_skip_reason",None);x.pop("web_skip_reason",None);return result\n        update_lead(id_,save_ai)\n    current=get_lead(id_) or {}\n    if cfg().get("auto_capsule_high_priority",False) and cfg().get("capsule_token") and current.get("outreach_priority_code") in ("P1","P2") and not (current.get("capsule") or {}).get("capsule_id"):\n        if job_id:_job_set(job_id,detail=f"Sending high-priority prospect to Capsule • {company}",company=company,current_url="")\n        update_lead(id_,lambda x:(x.update({"capsule":capsule_sync(x)}) or x["capsule"]))\n    return {"status":"done","company":company}\n\n\n_v423_old_run_progress_job=_run_progress_job\ndef _run_progress_job(job_id, action, ids):\n    # AI qualify on one company now uses the same resilient pipeline as Smart Finder.\n    if action=="ai_one":\n        return _v423_old_run_progress_job(job_id,"pipeline",ids)\n    if action!="web_one":\n        return _v423_old_run_progress_job(job_id,action,ids)\n    job=_job_get(job_id) or {};ids=list(ids or job.get("ids") or [])\n    awake=_begin_unattended_mode();awake_ok=bool(awake[1])\n    try:\n        if not ids:\n            _job_set(job_id,status="complete",percent=100,detail="Nothing to do",completed=0,remaining=0,finished_at=time.time(),resumable=False,awake_protected=False);return\n        _job_set(job_id,status="running",percent=2,detail="Finding public web presence…",completed=0,total=len(ids),remaining=len(ids),resumable=False,error="",awake_protected=awake_ok)\n        done=0;issues=[]\n        for id_ in ids:\n            l=get_lead(id_);company=(l or {}).get("company") or "Prospect"\n            if not l:issues.append({"id":id_,"company":company,"reason":"Prospect not found"});done+=1;continue\n            try:\n                l=_v423_resolve_presence(id_,l,job_id,company) or get_lead(id_) or l\n                if not l.get("website") and not l.get("facebook_url"):raise SkipProspect("No company website or Facebook business page found")\n                def progress(i,n,msg,url,pages):_job_set(job_id,detail=f"{msg} • {company}",current_url=url,page_index=i,page_total=n,pages_found=pages,company=company)\n                def enrich(x):\n                    ev=_v423_collect_evidence(id_,x,progress,job_id,company);x["web_evidence"]=ev;x["emails"]=merge_lists(x.get("emails",[]),ev.get("emails",[]))\n                    if ev.get("contact_page"):x["contact_page"]=ev["contact_page"]\n                    if ev.get("linkedin_url"):x["linkedin_url"]=ev["linkedin_url"]\n                    x.pop("web_skip_reason",None);return ev\n                ev=update_lead(id_,enrich) or {}\n                if len((ev.get("text") or "").strip())<120:raise SkipProspect("Facebook page found, but not enough public evidence could be read" if l.get("facebook_url") and not l.get("website") else "No usable website evidence")\n            except SkipProspect as ex:\n                reason=str(ex);issues.append({"id":id_,"company":company,"reason":reason});update_lead(id_,lambda x:(x.update({"web_skip_reason":reason}) or True))\n            done+=1;_job_set(job_id,completed=done,remaining=max(0,len(ids)-done),percent=round(done/max(1,len(ids))*100,1),issues=issues[-25:],last_updated_id=id_)\n        _job_set(job_id,status="complete",percent=100,detail=f"Website evidence complete • {done-len(issues)} updated • {len(issues)} skipped",completed=len(ids),remaining=0,finished_at=time.time(),resumable=False,issues=issues[-25:],awake_protected=False)\n    except Exception as ex:\n        _job_set(job_id,status="paused",error=str(ex),detail="Paused safely — completed work is saved",finished_at=time.time(),resumable=True,failure_kind=_v423_transient_kind(ex),awake_protected=False)\n    finally:\n        _end_unattended_mode(awake)\n\n\n_v423_old_resume_progress_job=resume_progress_job\ndef resume_progress_job(job_id):\n    with JOB_LOCK:\n        job=JOBS.get(job_id)\n        if not job:raise RuntimeError("Saved background job was not found.")\n        action=job.get("action","")\n        if action!="finder":\n            job=None\n    if job is None:return _v423_old_resume_progress_job(job_id)\n    with JOB_LOCK:\n        job=JOBS.get(job_id)\n        if job.get("status") in ("queued","running"):return dict(job)\n        stopped=bool(job.get("stopped")) and int(job.get("remaining",0) or 0)>0\n        if not job.get("resumable") and not stopped and job.get("status") not in ("paused","failed"):\n            raise RuntimeError("This Smart Finder session has already finished.")\n        job["status"]="queued";job["detail"]="Smart Finder resume queued — restoring saved position";job["error"]="";job["resumable"]=False;job["failure_kind"]="";job["stop_requested"]=False;job["stopped"]=False;job["finished_at"]=0;job["updated_at"]=time.time();_persist_jobs_locked()\n    threading.Thread(target=_run_smart_finder,args=(job_id,),daemon=True).start()\n    return _job_get(job_id)\n\n\n_v423_old_start_smart_finder=start_smart_finder\ndef start_smart_finder(query_limit=100,pages=1):\n    latest=_finder_job_latest()\n    if latest:\n        stopped=bool(latest.get("stopped")) and int(latest.get("remaining",0) or 0)>0\n        if (latest.get("status")=="paused" and latest.get("resumable")) or stopped:\n            return resume_progress_job(latest.get("id",""))\n    return _v423_old_start_smart_finder(query_limit,pages)\n'
JS="\n<script>\n(function(){\n async function v423Resume(){\n  try{\n   const s=await api('/api/finder/status');\n   if(!s||!s.id){toast('No saved Smart Finder session found.','warn',5000);return}\n   const j=await api('/api/job/resume',{id:s.id});\n   if(typeof paintFinderStatus==='function')paintFinderStatus(j);\n   if(typeof showProgress==='function')showProgress('Smart Finder • resumed');\n   if(typeof paintJob==='function')paintJob(j);\n   if(typeof pollFinderJob==='function')pollFinderJob(j.id);\n  }catch(e){toast(e.message||String(e),'bad',7000)}\n }\n window.resumeSmartFinder=v423Resume;\n function ensureBtn(){\n  ['finderDashStop','finderStopBtn'].forEach(function(id){\n   const stop=document.getElementById(id);if(!stop)return;\n   const rid=id==='finderDashStop'?'finderDashResumeV423':'finderResumeV423';\n   if(document.getElementById(rid))return;\n   const b=document.createElement('button');b.id=rid;b.className='btn green';b.textContent='Resume Smart Finder';b.style.display='none';b.onclick=v423Resume;stop.insertAdjacentElement('afterend',b);\n  });\n }\n async function refresh(){\n  ensureBtn();\n  try{\n   const s=await api('/api/finder/status');\n   const can=!!(s&&(s.status==='paused'&&s.resumable || s.stopped&&Number(s.remaining||0)>0));\n   ['finderDashResumeV423','finderResumeV423'].forEach(function(id){const b=document.getElementById(id);if(b)b.style.display=can?'inline-flex':'none'});\n  }catch(e){}\n }\n setTimeout(refresh,500);setInterval(refresh,2500);\n})();\n</script>\n"
